"""
PDF Export Service for Legal Notices using ReportLab.
Renders draft notices into formal, printable PDF documents with mandatory advocate disclaimers.
"""

import io
from reportlab.lib.pagesizes import letter, A4
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.platypus import (
    SimpleDocTemplate,
    Paragraph,
    Spacer,
    HRFlowable,
    Table,
    TableStyle
)

MANDATORY_DISCLAIMER = (
    "DISCLAIMER: This is a draft generated by an AI tool (NyayaSahayak) and does NOT constitute legal advice. "
    "Please have this notice reviewed and verified by a qualified advocate before signing or serving upon the recipient."
)


def generate_notice_pdf(draft_text: str, notice_title: str = "LEGAL DEMAND NOTICE") -> io.BytesIO:
    """
    Generates a clean PDF from the legal notice draft text and returns BytesIO buffer.
    """
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        rightMargin=54,
        leftMargin=54,
        topMargin=54,
        bottomMargin=54
    )

    styles = getSampleStyleSheet()

    # Custom styles
    title_style = ParagraphStyle(
        'NoticeTitle',
        parent=styles['Heading1'],
        fontName='Helvetica-Bold',
        fontSize=15,
        leading=18,
        alignment=1,  # Center
        textColor=colors.HexColor('#1a365d')
    )

    disclaimer_style = ParagraphStyle(
        'NoticeDisclaimer',
        parent=styles['Normal'],
        fontName='Helvetica-Bold',
        fontSize=8,
        leading=10,
        alignment=1,
        textColor=colors.HexColor('#b71c1c')
    )

    body_style = ParagraphStyle(
        'NoticeBody',
        parent=styles['Normal'],
        fontName='Helvetica',
        fontSize=10,
        leading=15,
        alignment=4,  # Justify
        textColor=colors.HexColor('#222222')
    )

    story = []

    # Mandatory Disclaimer Top Banner Box
    disclaimer_table = Table(
        [[Paragraph(MANDATORY_DISCLAIMER, disclaimer_style)]],
        colWidths=[A4[0] - 108]
    )
    disclaimer_table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor('#ffebee')),
        ('BOX', (0, 0), (-1, -1), 1, colors.HexColor('#d32f2f')),
        ('TOPPADDING', (0, 0), (-1, -1), 6),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 6),
        ('LEFTPADDING', (0, 0), (-1, -1), 8),
        ('RIGHTPADDING', (0, 0), (-1, -1), 8),
    ]))

    story.append(disclaimer_table)
    story.append(Spacer(1, 15))

    # Notice Header
    story.append(Paragraph(notice_title.upper(), title_style))
    story.append(Spacer(1, 4))
    story.append(HRFlowable(width="100%", thickness=1.5, color=colors.HexColor('#1a365d'), spaceAfter=14))

    # Format notice text paragraphs
    paragraphs = draft_text.strip().split("\n\n")
    for para in paragraphs:
        cleaned_para = para.strip().replace("\n", "<br/>")
        if cleaned_para:
            story.append(Paragraph(cleaned_para, body_style))
            story.append(Spacer(1, 10))

    # Bottom Footer Disclaimer
    story.append(Spacer(1, 15))
    story.append(HRFlowable(width="100%", thickness=0.5, color=colors.HexColor('#cccccc'), spaceAfter=8))
    footer_text = (
        "Generated via NyayaSahayak: AI Legal Aid Assistant • Based on Indian statutory provisions • "
        "Free Legal Aid Helpline: 15100"
    )
    footer_style = ParagraphStyle(
        'NoticeFooter',
        parent=styles['Normal'],
        fontName='Helvetica-Oblique',
        fontSize=7,
        leading=9,
        alignment=1,
        textColor=colors.HexColor('#666666')
    )
    story.append(Paragraph(footer_text, footer_style))

    # Build PDF
    doc.build(story)
    buffer.seek(0)
    return buffer

